/// The gallery's example of `RubberBand`, with its settings taken from the story.
#[allow(unused_variables, unused_mut, clippy::redundant_clone, clippy::let_and_return, clippy::clone_on_copy)]
fn render(args: &Args) -> AnyView {
    Box::new({
        let arg_disabled = args.bool("disabled");
        let arg_keep = args.bool("keep");
        let arg_label = args.text("label");

        let selection = State::new(None::<Rect>);
        let chosen = State::new(args.text("chosen"));
        let told = chosen.clone();
        VStack::new((Text::bound(&chosen, Clone::clone), {
            let mut it = RubberBand::new(selection.binding())
                .on_select(move |r| told.set(format!("{:.0} × {:.0}", r.width(), r.height())))
                .size(320.0, 130.0);
            it = it.disabled(arg_disabled);
            it = it.keep(arg_keep);
            if !arg_label.is_empty() {
                it = it.label(arg_label.clone());
            }
            it
        }))
        .spacing(8.0)
    })
}

impl ComponentBook for RubberBand {
    fn book() -> Meta {
        Meta::new("Media/RubberBand", render)
            .summary("A rectangle drawn with a drag, in the units of the content, selected on release.")
            .arg(ArgType::bool("disabled", false))
            .arg(ArgType::bool("keep", true))
            .arg(ArgType::text("label", "").description("Empty leaves it as the component has it."))
            .arg(ArgType::text("chosen", "Drag over the box").description("How the example starts."))
            .story("Example", Args::new())
            .story("Disabled", Args::new().with("disabled", true))
    }
}
